.fl1.as-center.wmn0,
    .question-summary .question-hyperlink,
    .ff-mono,
    .post-tag {
        font-family: var(--vknDefaultFontFamily);
    }

    #question-header .question-hyperlink {
        font-family: var(--vknDefaultFontFamily);
    }

    .statsBox .number {
        font-family: var(--vknDefaultFontFamily);
    }

    body {
        zoom: 100%;
        --fs-body3: 18px;
    }

    #mainbar h3 {
        font-weight: 500;
    }

    html,
    body,
    div,
    applet,
    object,
    iframe,
    h1,
    h2,
    h3,
    h4,
    h5,
    h6,
    p,
    blockquote,
    a,
    abbr,
    acronym,
    address,
    big,
    cite,
    del,
    dfn,
    em,
    img,
    ins,
    kbd,
    q,
    s,
    samp,
    small,
    strike,
    strong,
    sub,
    sup,
    tt,
    var,
    b,
    u,
    i,
    center,
    dl,
    dt,
    dd,
    ol,
    ul,
    li,
    fieldset,
    form,
    label,
    legend,
    table,
    caption,
    tbody,
    tfoot,
    thead,
    tr,
    th,
    td,
    article,
    aside,
    canvas,
    details,
    embed,
    figure,
    figcaption,
    footer,
    header,
    hgroup,
    menu,
    nav,
    output,
    ruby,
    section,
    summary,
    time,
    mark,
    audio,
    video,
    ul.comments-list .comment-text,
    .post-text,
    .wmd-preview,
    .comment-copy,
    .question-status,
    .excerpt,
    .message-text,
    .message-text * {
        font-family: var(--vknDefaultFontFamily) !important;
    }

    .hljs-keyword {
        font-style: normal;
    }

    .question-hyperlink {
        font-size: 14px;
    }

    textarea,
    textarea.wmd-input,
    textarea#wmd-input,
    .ff-mono,
    .s-prose code {
        font-family: var(--vknMonoFontFamily) !important;
        font-size: var(--vknMonoFontSize) !important;
        font-weight: var(--vknMonoFontWeight);
    }

    .s-sidebarwidget--content > * {
        font-family: var(--vknMonoFontFamily);
        font-size: var(--vknMonoFontSize) !important;
    }

    .s-progress--label {
        font-size: 11px;
    }

    select,
    input,
    button,
    .button,
    a.button:link,
    .btn,
    [class*="btn-"],
    .hero-box.double-panel .panel.white .btn {
        font-size: smaller;
    }

    kbd {
        font-size: 11px;
        background: lightgray;
        box-shadow: 0 1px 0 rgba(12, 13, 14, 0.2),
        0 0 0 2px lightgrey inset;
        color: black;
    }

    .kwd,
    .dec,
    .atn {
        font-style: italic;
    }

    .grid--cell {
        font-size: 12px;
    }

    .topbar-dialog .modal-content .message-text h4 {
        font-family: var(--vknDefaultFontFamily) !important;
    }

    .grid__allcells6 > .grid,
    .grid__allcells6 > .grid--cell {
        flex-basis: 40%;
    }

    span.grid--cell {
        font-size: 100%;
    }

    .account-container .account-stat .account-number {
        font-family: inherit;
    }

    .narrow .status {
        min-width: 60px;
    }

    .js-new-post-activity {
        margin-bottom: 8px;
        margin-right: 8px;
    }

    .js-new-post-activity > .d-block {
        font-size: 25px;
    }

    .fs-headline2 {
        font-size: 2.15385rem !important;
    }

    p code {
        font-style: initial;
    }

    p{
        text-align: left !important;
    }

    .s-sidebarwidget.js-join-leave-container.mb16,
    .s-sidebarwidget.s-sidebarwidget__yellow.s-anchors.s-anchors__grayscale.mb16 {
        display: none !important;
    }

    pre.s-code-block {
        line-height: 1.3;
        letter-spacing: 0.3px;
    }

    #newsletter-ad,
    #mainbar > .mb24 {
        display: none;
    }

    .s-post-summary--stats-item.s-post-summary--stats-item__emphasized {
        font-size: 12px;
    }

    .s-post-summary--content-title {
        font-weight: 500 !important;
        font-size: 16px !important;
    }

    .answer-hyperlink, .question-hyperlink{
        font-weight: 500 !important;
        font-size: 14px !important;
    }

